import{_ as a,o as i,c as e,a0 as t}from"./chunks/framework.BLL-IG04.js";const k=JSON.parse('{"title":"Tutorial: your first audit","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/first-run.md","filePath":"tutorials/first-run.md"}'),n={name:"tutorials/first-run.md"};function l(h,s,p,o,d,r){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="tutorial-your-first-audit" tabindex="-1">Tutorial: your first audit <a class="header-anchor" href="#tutorial-your-first-audit" aria-label="Permalink to &quot;Tutorial: your first audit&quot;">​</a></h1><p>Goal: point mimus at a repo&#39;s docs and see which claims are still true — docs-as-tests, in minutes.</p><h2 id="_1-init" tabindex="-1">1. Init <a class="header-anchor" href="#_1-init" aria-label="Permalink to &quot;1. Init&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> your-repo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mimus</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span></code></pre></div><p>Writes a commented <code>mimus.toml</code> and a <code>rules/</code> dir. Defaults:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sources</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">docs = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;README.md&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;docs/**/*.md&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;AGENTS.md&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;project/**/*.md&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">comments = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cards = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;.kuda/modules/*.yaml&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">check</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mechanical = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">semantic = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre></div><h2 id="_2-check" tabindex="-1">2. Check <a class="header-anchor" href="#_2-check" aria-label="Permalink to &quot;2. Check&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mimus</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p>Claim extraction scans every configured doc: backticked paths, shell commands, symbol names, counts, links. Each claim is verified against reality — the filesystem, PATH, the kuda index (symbol claims need <code>kuda sync</code>; without an index they&#39;re silence, not failures):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>README.md:42 [error] \`src/old_api.rs\` — ./src/old_api.rs does not exist</span></span>
<span class="line"><span>docs/guide.md:17 [warn] \`cargo bench\` — binary \`cargo-bench\` not found in PATH</span></span>
<span class="line"><span>2 violation(s)</span></span></code></pre></div><p>Exit code is <code>1</code> on any <code>error</code>-severity violation — docs drift becomes a gateable signal.</p><h2 id="_3-make-a-claim-and-watch-it-get-caught" tabindex="-1">3. Make a claim and watch it get caught <a class="header-anchor" href="#_3-make-a-claim-and-watch-it-get-caught" aria-label="Permalink to &quot;3. Make a claim and watch it get caught&quot;">​</a></h2><p>Add a line to your README referencing a file that does not exist:</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">See </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`nonexistent/dead.rs\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> for the implementation.</span></span></code></pre></div><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mimus</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>README.md:N [error] \`nonexistent/dead.rs\` — ./nonexistent/dead.rs does not exist</span></span></code></pre></div><p>Every violation is claim + evidence + (when mechanical) a fix — the evidence bar is the design rule, see <a href="./../explanation/architecture.html">architecture</a>.</p><h2 id="_4-author-a-convention" tabindex="-1">4. Author a convention <a class="header-anchor" href="#_4-author-a-convention" aria-label="Permalink to &quot;4. Author a convention&quot;">​</a></h2><p><code>rules/</code> is data. Add <code>rules/no-todos.toml</code>:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;no-todos&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">message = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;TODO left in committed source&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">severity = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;warn&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">files = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;src/**/*.rs&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">match</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">kind = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;source-pattern&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pattern = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;TODO|FIXME&quot;</span></span></code></pre></div><p><code>mimus check</code> now flags every TODO — a convention encoded as a file, not a code change. See <a href="./../how-to/rules-authoring.html">authoring rules</a>.</p><h2 id="_5-audit-the-memory-layer" tabindex="-1">5. Audit the memory layer <a class="header-anchor" href="#_5-audit-the-memory-layer" aria-label="Permalink to &quot;5. Audit the memory layer&quot;">​</a></h2><p>If the repo is kuda-indexed:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kuda</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mimus</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> audit</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fresh        kuda-store</span></span>
<span class="line"><span>drifted      kuda-core</span></span>
<span class="line"><span>20 fresh, 1 drifted, 0 contradicted</span></span></code></pre></div><p>Cards whose <code>verify:</code> files changed since sync report <code>drifted</code>; missing files report <code>contradicted</code>.</p><h2 id="you-have-built" tabindex="-1">You have built <a class="header-anchor" href="#you-have-built" aria-label="Permalink to &quot;You have built&quot;">​</a></h2><p>A falsification layer: every factual claim in your docs is now a test that fails loudly when reality moves.</p><p>Next: <a href="./../how-to/ci-gate.html">gate CI on it</a>, <a href="./../how-to/rules-authoring.html">write rules</a>.</p>`,29)])])}const u=a(n,[["render",l]]);export{k as __pageData,u as default};
